# Shared fixture primitives for development-unit admission and recovered continuation tests.
# Callers import production modules explicitly before dot-sourcing this file.

function Assert-Envelope([bool]$Condition,[string]$Message){if(-not$Condition){throw "Development-envelope self-test failed: $Message"}}

function Write-EnvelopeJson([string]$Path,[object]$Value){$parent=Split-Path $Path -Parent;if(-not(Test-Path $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 64)+"`n"),[Text.UTF8Encoding]::new($false))}

function Copy-Envelope([object]$Value){$Value|ConvertTo-Json -Depth 64|ConvertFrom-Json -DateKind String}

function Get-EnvelopeLockFingerprint([object]$Value){$copy=Copy-Envelope $Value;$copy.lock_fingerprint='0'*64;Get-EnvelopeCanonicalJsonSha256 $copy}

function Invoke-EnvelopeGit([string]$Path,[string[]]$Arguments){$output=@(& git -C $Path @Arguments 2>&1);if($LASTEXITCODE-ne0){throw "Envelope Git fixture failed: git -C $Path $($Arguments -join ' ') $($output -join ' ')"};@($output|ForEach-Object{[string]$_})}

function Get-EnvelopeProtocolModule{if($null-eq$protocolModule){throw 'MorphospaceProtocolCommon retained module is unavailable.'};$protocolModule}

function Read-EnvelopeProtocolJson([string]$Path){$module=Get-EnvelopeProtocolModule;&$module {param($p)Read-MorphospaceProtocolJson -Path $p} $Path}

function Get-EnvelopeCanonicalJsonSha256([object]$Value){$module=Get-EnvelopeProtocolModule;&$module {param($v)Get-MorphospaceCanonicalJsonSha256 -Value $v} $Value}

function Get-EnvelopeFileSha256([string]$Path){$module=Get-EnvelopeProtocolModule;&$module {param($p)Get-MorphospaceFileSha256 -Path $p} $Path}

function Write-EnvelopeCanonicalJson([string]$Path,[object]$Value){$module=Get-EnvelopeProtocolModule;[byte[]]$bytes=&$module {param($v)ConvertTo-MorphospaceProtocolJsonBytes $v} $Value;[IO.File]::WriteAllBytes($Path,$bytes)}

function Get-EnvelopeWorkspaceByteInventorySha256([string]$Workspace){
  $root=[IO.Path]::GetFullPath($Workspace);$rows=@(Get-ChildItem -LiteralPath $root -Recurse -File|Sort-Object FullName|ForEach-Object{[pscustomobject][ordered]@{path=$_.FullName.Substring($root.Length).TrimStart('\').Replace('\','/');sha256=Get-EnvelopeFileSha256 $_.FullName;bytes=$_.Length}})
  Get-EnvelopeCanonicalJsonSha256 $rows
}

function New-EnvelopeReplacementAdmission([object]$Template,[string]$Workspace,[string]$AdmissionId,[string]$UnitId){
  if ($Template.PSObject.Properties.Name -notcontains 'admission_kind') { $Template=Copy-Envelope $Template; $Template|Add-Member -NotePropertyName admission_kind -NotePropertyValue 'ordinary' }
  $replacement=Copy-Envelope $Template;$replacement.admission_id=$AdmissionId;$replacement.unit_id=$UnitId;$replacement.unit.unit_id=$UnitId;$replacement.unit.status='proposed';$replacement.unit.objective="Exercise the exact authenticated replacement journey for $UnitId.";$replacement.unit.instruction_impact='none';$replacement.unit.instruction_surfaces=@();$replacement.unit.instruction_none_justification='The replacement fixture changes no portable instruction contract.'
  $state=Read-EnvelopeProtocolJson (Join-Path $Workspace 'workspace.state.json');$eventsPath=Join-Path $Workspace 'iteration-events.jsonl';$tail=@(Get-Content -LiteralPath $eventsPath|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json})[-1]
  $replacement.expected.state_sha256=Get-EnvelopeCanonicalJsonSha256 $state;$replacement.expected.events_sha256=Get-EnvelopeFileSha256 $eventsPath;$replacement.expected.events_length=([IO.FileInfo]$eventsPath).Length;$replacement.expected.event_tail_id=[string]$tail.event_id
  return $replacement
}

